7141: // MARK: - Peer ID Validation & Normalization
7142: 
7143: struct PeerIdValidator {
7144:     /// Normalizes a Peer ID based on its type.
7145:     /// - Identity IDs (64-char hex) are converted to lowercase.
7146:     /// - libp2p Peer IDs (Base58) are preserved as-is (they are case-sensitive).
7147:     static func normalize(_ id: String) -> String {
7148:         let trimmed = id.trimmingCharacters(in: .whitespacesAndNewlines)
7149:         if isIdentityId(trimmed) {
7150:             return trimmed.lowercased()
7151:         }
7152:         return trimmed
7153:     }
7154: 
7155:     /// Checks if the given string is a 64-character hex identity ID.
7156:     static func isIdentityId(_ id: String) -> Bool {
7157:         guard id.count == 64 else { return false }
7158:         return id.unicodeScalars.allSatisfy { scalar in
7159:             CharacterSet(charactersIn: "0123456789abcdefABCDEF").contains(scalar)
7160:         }
7161:     }
7162: 
7163:     /// Checks if the given string starts with common libp2p Peer ID prefixes.
7164:     static func isLibp2pPeerId(_ id: String) -> Bool {
7165:         return id.hasPrefix("12D3Koo") || id.hasPrefix("Qm")
7166:     }
7167: 
7168:     /// Performs a case-sensitive comparison after normalization.
7169:     static func isSame(_ id1: String, _ id2: String) -> Bool {
7170:         return normalize(id1) == normalize(id2)
7171:     }
7172: }

