61: /// Priority queue of outgoing data
62: #[derive(Debug, Clone)]
63: pub struct OutgoingQueue {
64:     items: Vec<PendingSend>,
65: }
66: 
67: impl OutgoingQueue {
68:     /// Create a new outgoing queue
69:     pub fn new() -> Self {
70:         Self { items: Vec::new() }
71:     }
72: 
73:     /// Add an item to the queue (maintains priority order)
74:     pub fn enqueue(&mut self, item: PendingSend) {
75:         self.items.push(item);
76:         // Sort so highest priority items are first
77:         self.items
78:             .sort_by_key(|item| std::cmp::Reverse(item.priority));
79:     }
