14: #[derive(Serialize, Deserialize)]
15: struct LegacyQueuedMessage {
16:     pub message_id: String,
17:     pub recipient_id: String,
18:     pub envelope_data: Vec<u8>,
19:     pub queued_at: u64,
20:     pub attempts: u32,
21:     pub next_retry_at: Option<u64>,
22:     #[serde(default = "default_false")]
23:     pub in_custody: bool,
24:     #[serde(default = "default_zero")]
25:     pub custody_established_at: u64,
26:     #[serde(default = "default_enqueued")]
27:     pub state: MessageState,
28: }
29: 
30: fn deserialize_queued_message(data: &[u8]) -> Result<QueuedMessage, bincode::Error> {
31:     if data.is_empty() {
32:         return Err(Box::new(bincode::ErrorKind::Io(std::io::Error::new(
33:             std::io::ErrorKind::UnexpectedEof,
34:             "empty",
35:         ))));
36:     }
37:     // If the first byte is 1, it's the new versioned format.
38:     // Legacy format starts with a String length. Since string lengths are usually 36 (for UUIDs),
39:     // their first byte is 36, not 1.
40:     if data[0] == 1 {
41:         bincode::deserialize(data)
42:     } else {
43:         let legacy: LegacyQueuedMessage = bincode::deserialize(data)?;
44:         Ok(QueuedMessage {
45:             version: 1,
46:             message_id: legacy.message_id,
47:             recipient_id: legacy.recipient_id,
48:             envelope_data: legacy.envelope_data,
49:             queued_at: legacy.queued_at,
50:             attempts: legacy.attempts,
51:             next_retry_at: legacy.next_retry_at,
52:             in_custody: legacy.in_custody,
53:             custody_established_at: legacy.custody_established_at,
54:             state: legacy.state,
55:         })
56:     }
57: }
