1: // Per-message encryption: X25519 ECDH + XChaCha20-Poly1305
2: //
3: // Flow:
4: // 1. Convert sender's Ed25519 signing key → X25519 static secret
5: // 2. Generate ephemeral X25519 keypair
6: // 3. ECDH: ephemeral_secret × recipient_x25519_public → shared_secret
7: // 4. KDF: Blake3::derive_key(shared_secret) → symmetric_key
8: // 5. Encrypt: XChaCha20-Poly1305(symmetric_key, random_nonce, plaintext)
9: // 6. Output: Envelope { sender_pub, ephemeral_pub, nonce, ciphertext }
10: //
11: // Recipient reverses:
12: // 1. Convert recipient's Ed25519 key → X25519 static secret
13: // 2. ECDH: recipient_secret × ephemeral_public → shared_secret
14: // 3. KDF: same derivation → symmetric_key
15: // 4. Decrypt: XChaCha20-Poly1305(symmetric_key, nonce, ciphertext)
16: 
17: use anyhow::{bail, Result};
18: use chacha20poly1305::{
19:     aead::{Aead, KeyInit, Payload},
20:     XChaCha20Poly1305, XNonce,
21: };
22: use ed25519_dalek::{Signature as Ed25519Signature, Signer, SigningKey, Verifier, VerifyingKey};
23: use rand::RngCore;
24: use x25519_dalek::{EphemeralSecret, PublicKey as X25519PublicKey, StaticSecret};
25: use zeroize::Zeroize;
26: 
27: /// KDF context string for deriving encryption keys from ECDH shared secrets.
28: /// Changing this breaks compatibility with all existing messages.
29: pub const KDF_CONTEXT: &str = "iron-core v2 message encryption 2026-02-05";
30: 
31: /// Convert an Ed25519 signing key to an X25519 static secret for ECDH.
32: ///
33: /// Ed25519 and X25519 share the same underlying curve (Curve25519),
34: /// so we can derive X25519 keys from Ed25519 keys deterministically.
35: /// The conversion uses the clamped SHA-512 hash of the Ed25519 secret key,
36: /// which is how Ed25519 internally derives its scalar.
37: pub fn ed25519_to_x25519_secret(signing_key: &SigningKey) -> StaticSecret {
38:     // Ed25519 secret scalar is SHA-512(secret_key_bytes)[0..32], clamped.
39:     // x25519-dalek StaticSecret expects the raw 32-byte secret and does its own clamping.
40:     let mut hash = <sha2::Sha512 as sha2::Digest>::digest(signing_key.to_bytes());
41:     let mut secret_bytes = [0u8; 32];
42:     secret_bytes.copy_from_slice(&hash[..32]);
43: 
44:     let secret = StaticSecret::from(secret_bytes);
45: 
46:     // Zeroize intermediates
47:     secret_bytes.zeroize();
48:     hash.as_mut_slice().zeroize();
49: 
50:     secret
51: }
52: 
53: /// Validate that a hex-encoded Ed25519 public key is well-formed.
54: ///
55: /// Checks:
56: /// 1. Hex decoding succeeds
57: /// 2. Length is exactly 32 bytes
58: /// 3. Bytes represent a valid compressed Ed25519 point
59: ///
60: /// Returns an error with a specific message if validation fails.
61: pub fn validate_ed25519_public_key(public_key_hex: &str) -> Result<()> {
62:     use curve25519_dalek::edwards::CompressedEdwardsY;
63: 
64:     // Decode hex
65:     let public_key_bytes = hex::decode(public_key_hex)
66:         .map_err(|_| anyhow::anyhow!("Invalid hex encoding in public key"))?;
