70:         bail!(
71:             "Public key must be exactly 32 bytes (64 hex characters), got {} bytes ({} hex characters)",
72:             public_key_bytes.len(),
73:             public_key_hex.len()
74:         );
75:     }
76: 
77:     // Validate Ed25519 format by attempting decompression
78:     let mut key_array = [0u8; 32];
79:     key_array.copy_from_slice(&public_key_bytes);
