13: /// Check if a 64-hex string looks like a public key (valid Ed25519 curve point)
14: pub fn is_valid_public_key(hex_str: &str) -> bool {
15:     if hex_str.len() != 64 || !hex_str.chars().all(|c| c.is_ascii_hexdigit()) {
16:         return false;
17:     }
18:     if let Ok(bytes) = hex::decode(hex_str) {
19:         if let Ok(arr) = <[u8; 32]>::try_from(bytes.as_slice()) {
20:             return ed25519_dalek::VerifyingKey::from_bytes(&arr).is_ok();
21:         }
22:     }
23:     false
24: }
25: 
26: /// Check if a 64-hex string is a valid identity_id format (always valid if 64 hex chars)
27: pub fn is_valid_identity_id(hex_str: &str) -> bool {
28:     hex_str.len() == 64 && hex_str.chars().all(|c| c.is_ascii_hexdigit())
