42:     // not a valid curve point) is rejected rather than double-hashed.
43:     if !is_valid_public_key(public_key_hex) {
44:         return None;
45:     }
46:     let bytes = hex::decode(public_key_hex).ok()?;
47:     Some(hex::encode(blake3::hash(&bytes).as_bytes()))
48: }
