19: /// Versioned wrapper for sync messages to enable protocol evolution
20: #[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
21: pub struct VersionedSyncMessage {
22:     /// Schema version for this message
23:     pub schema_version: u32,
24:     /// The actual sync message payload
25:     pub payload: SyncMessage,
26: }
27: 
28: impl VersionedSyncMessage {
29:     /// Create a new versioned sync message with the current schema version
30:     pub fn new(payload: SyncMessage) -> Self {
31:         Self {
32:             schema_version: SYNC_SCHEMA_VERSION,
33:             payload,
34:         }
35:     }
36: 
37:     /// Validate that the message schema version matches our expected version
38:     pub fn validate(&self) -> Result<(), MeshError> {
39:         if self.schema_version != SYNC_SCHEMA_VERSION {
40:             return Err(MeshError::VersionMismatch {
41:                 expected: SYNC_SCHEMA_VERSION,
42:                 received: self.schema_version,
43:             });
44:         }
45:         Ok(())
46:     }
47: 
48:     /// Serialize VersionedSyncMessage to bytes using bincode
49:     pub fn to_bytes(&self) -> Result<Vec<u8>, DriftError> {
50:         bincode::serialize(self).map_err(|e| DriftError::DecompressionFailed(e.to_string()))
51:     }
52: 
53:     /// Deserialize and validate VersionedSyncMessage from bytes
54:     pub fn from_bytes(data: &[u8]) -> Result<Self, DriftError> {
55:         let msg: VersionedSyncMessage = bincode::deserialize(data)
56:             .map_err(|e| DriftError::DecompressionFailed(e.to_string()))?;
57:         msg.validate()
58:             .map_err(|e| DriftError::DecompressionFailed(e.to_string()))?;
59:         Ok(msg)
60:     }
