16: 
17: /// Maximum encoded message size: 256 KB
18: /// This prevents memory exhaustion from malicious oversized messages.
19: pub const MAX_MESSAGE_SIZE: usize = 256 * 1024;
20: 
21: /// Maximum text payload: 8 KB (8192 bytes)
22: pub const MAX_PAYLOAD_SIZE: usize = 8 * 1024;
23: 
24: /// Validate plaintext payload size against the messaging contract.
25: pub fn validate_payload_size(payload: &[u8]) -> Result<()> {
26:     if payload.len() > MAX_PAYLOAD_SIZE {
27:         bail!(
28:             "Payload too large: {} bytes (max {})",
29:             payload.len(),
30:             MAX_PAYLOAD_SIZE
31:         );
32:     }
33:     Ok(())
34: }
35: 
36: /// Serialize a Message to bytes (bincode)
37: pub fn encode_message(msg: &Message) -> Result<Vec<u8>> {
38:     validate_payload_size(&msg.payload)?;
39: 
40:     let bytes = bincode::serialize(msg)?;
41: 
42:     if bytes.len() > MAX_MESSAGE_SIZE {
43:         bail!(
44:             "Encoded message too large: {} bytes (max {})",
45:             bytes.len(),
46:             MAX_MESSAGE_SIZE
47:         );
48:     }
49: 
50:     Ok(bytes)
51: }
52: 
53: /// Deserialize bytes to a Message
54: pub fn decode_message(bytes: &[u8]) -> Result<Message> {
55:     if bytes.len() > MAX_MESSAGE_SIZE {
56:         bail!(
57:             "Message too large: {} bytes (max {})",
58:             bytes.len(),
59:             MAX_MESSAGE_SIZE
60:         );
61:     }
62: 
63:     let msg: Message = bincode::deserialize(bytes)?;
64:     Ok(msg)
65: }
