1: // Per-peer backoff state machine for graceful dial policy.
2: //
3: // This module implements P1 Item 3: Per-Peer Backoff State Machine (max 3 concurrent dials)
4: // and P1 Item 4: Prefer Circuit-Relay After Connection Established.
5: //
6: // Philosophy: Each peer maintains attempt_count, last_attempt_ts, and backoff_duration.
7: // The global dial orchestrator enforces max 3 concurrent outbound dials. Exponential
8: // backoff ranges from 1s to 30s (capped). On successful connection, backoff resets.
9: //
10: // Circuit-relay preference: Once a peer connects, we add circuit-relay multiaddrs
11: // to the candidate ladder in order: direct → relay → fallback.
12: 
13: use libp2p::{Multiaddr, PeerId};
14: use parking_lot::RwLock;
15: use std::collections::{HashMap, HashSet};
16: use std::sync::Arc;
17: use tracing::{debug, info, warn};
18: use web_time::{Duration, Instant};
19: 
20: /// Per-peer backoff state tracking.
21: #[derive(Debug, Clone)]
22: pub struct PerPeerBackoffState {
23:     /// Number of failed dial attempts (0-3). At 3, peer is considered dead.
24:     pub attempt_count: u32,
25:     /// Timestamp of the last dial attempt to this peer.
26:     pub last_attempt_ts: Instant,
27:     /// Current backoff duration (1s → 2s → 4s → 8s → 16s → 30s capped).
28:     pub backoff_duration: Duration,
29:     /// Whether this peer is marked as dead for this session (permanent failure).
30:     pub is_dead: bool,
31:     /// Optional peer ID if known at registration time.
32:     pub peer_id: Option<PeerId>,
33: }
34: 
35: impl PerPeerBackoffState {
36:     /// Create a new backoff state with initial backoff of 1 second.
37:     pub fn new(peer_id: Option<PeerId>) -> Self {
38:         Self {
39:             attempt_count: 0,
40:             last_attempt_ts: Instant::now(),
41:             backoff_duration: Duration::from_secs(1),
42:             is_dead: false,
43:             peer_id,
44:         }
45:     }
46: 
47:     /// Check if this peer is eligible for a dial attempt right now.
48:     pub fn is_eligible(&self) -> bool {
49:         if self.is_dead {
50:             return false;
51:         }
52:         if self.attempt_count >= 3 {
53:             return false;
54:         }
55:         // Allow the first attempt immediately.
56:         if self.attempt_count == 0 {
57:             return true;
58:         }
59:         Instant::now() >= self.last_attempt_ts + self.backoff_duration
60:     }
61: 
62:     /// Record a failed dial attempt: increment attempt_count and double backoff (capped at 30s).
63:     pub fn on_dial_failure(&mut self) {
64:         self.attempt_count += 1;
65:         self.last_attempt_ts = Instant::now();
66: 
67:         // Double the backoff duration, capped at 30 seconds.
68:         let doubled = self.backoff_duration.as_secs() * 2;
69:         self.backoff_duration = Duration::from_secs(doubled.min(30));
70: 
71:         debug!(
72:             peer_id=?self.peer_id,
73:             attempt_count=self.attempt_count,
74:             backoff_secs=self.backoff_duration.as_secs(),
75:             "[DIAL-BACKOFF] Incremented attempt count and backoff"
76:         );
77: 
78:         // After 3 attempts, mark as dead for this session.
79:         if self.attempt_count >= 3 {
80:             warn!(

